  4→  // The intake questions per category, in form order. Keys match what the server
  5→  // accepts; blank answers are allowed and are what the follow-up round is for.
  6→  var QUESTIONNAIRES = {
  7→    route_deviation: [
  8→      { key: "what_went_wrong", label: "What went wrong?" },
  9→      { key: "expected_route", label: "What route did the app show you, and roughly how long was it?" },
 10→      { key: "was_route_agreed", label: "Did you and the driver agree to take a different route?" },
 11→      { key: "asked_driver_to_stop", label: "Did you ask the driver to stop anywhere along the way?" },
 12→      { key: "safety_concern", label: "At any point were you worried for your safety?" }
 13→    ],
 14→    no_show_charge: [
 15→      { key: "what_went_wrong", label: "What went wrong?" },
 16→      { key: "where_were_you", label: "Where were you when the trip was meant to start?" },
 17→      { key: "did_driver_contact_you", label: "Did the driver try to contact you?" },
 18→      { key: "safety_concern", label: "At any point were you worried for your safety?" }
 19→    ]
 20→  };
 21→
 22→  var CATEGORIES = [
 23→    { id: "route_deviation", label: "My trip went the wrong way" },
 24→    { id: "no_show_charge", label: "I was charged for a trip that did not happen" },
 25→    { id: "property_damage_mess", label: "Property damage or a mess left behind" },
 26→    { id: "safety_incident", label: "A safety incident" },
 27→    { id: "other", label: "Something else" }
 28→  ];
 29→
 30→  var STATUS_HEADINGS = {
 31→    decided: "We have made a decision",
 32→    under_review: "Your case is still under review",
 33→    passed_to_support: "Your report has been passed to our support team",
 34→    needs_info: "We need a little more information"
 35→  };
 36→
 37→  var state = {
 38→    category: null,
 39→    tripId: null,
 40→    trips: [],
 41→    runId: null
 42→  };
 43→
 44→  var stepCategory = document.getElementById("step-category");
 45→  var stepTrip = document.getElementById("step-trip");
 46→  var stepDetails = document.getElementById("step-details");
 47→  var outcomePanel = document.getElementById("outcome");
 48→  var categoryOptions = document.getElementById("category-options");
 49→  var tripOptions = document.getElementById("trip-options");
 50→  var questionList = document.getElementById("question-list");
 51→  var questionBoxes = document.getElementById("question-boxes");
 52→  var outcomeTitle = document.getElementById("outcome-title");
 53→  var outcomeReference = document.getElementById("outcome-reference");
 54→  var outcomeMessage = document.getElementById("outcome-message");
 55→  var outcomeQuestions = document.getElementById("outcome-questions");
 56→  var outcomeStatus = document.getElementById("outcome-status");
