 58→  function element(tag, className, text) {
 59→    var node = document.createElement(tag);
 60→    if (className) {
 61→      node.className = className;
 62→    }
 63→    if (text !== undefined && text !== null) {
 64→      node.textContent = String(text);
 65→    }
 66→    return node;
 67→  }
 68→
 69→  function showError(id, message) {
 70→    var node = document.getElementById(id);
 71→    node.textContent = message;
 72→    node.hidden = false;
 73→  }
 74→
 75→  function clearError(id) {
 76→    var node = document.getElementById(id);
 77→    node.textContent = "";
 78→    node.hidden = true;
 79→  }
 80→
 81→  function show(node) {
 82→    node.hidden = false;
 83→  }
 84→
 85→  function hide(node) {
 86→    node.hidden = true;
 87→  }
 88→
 89→  function request(method, path, body) {
 90→    var options = { method: method };
 91→    if (body !== undefined) {
 92→      options.headers = { "Content-Type": "application/json" };
 93→      options.body = JSON.stringify(body);
 94→    }
 95→    return fetch(path, options).then(function (response) {
 96→      return response.json().then(function (payload) {
 97→        if (!response.ok) {
 98→          var reason = payload && payload.error ? payload.error : "Something went wrong. Please try again.";
 99→          throw new Error(reason);
100→        }
101→        return payload;
102→      });
103→    });
104→  }
