106→  // ------------------------------------------------------------- step one
107→
108→  CATEGORIES.forEach(function (category) {
109→    var card = element("button", "option-card", category.label);
110→    card.type = "button";
111→    card.addEventListener("click", function () {
112→      state.category = category.id;
113→      Array.prototype.forEach.call(categoryOptions.children, function (child) {
114→        child.classList.remove("selected");
115→      });
116→      card.classList.add("selected");
117→      document.getElementById("category-next").disabled = false;
118→      // Changing the category resets everything downstream (R3 page side): the trip
119→      // list belongs to the category, so a trip picked for one category must never
120→      // survive a switch to another.
121→      state.tripId = null;
122→      while (tripOptions.firstChild) {
123→        tripOptions.removeChild(tripOptions.firstChild);
124→      }
125→      document.getElementById("trip-next").disabled = true;
126→      clearError("trip-error");
127→      clearError("details-error");
128→      hide(stepTrip);
129→      hide(stepDetails);
130→    });
131→    categoryOptions.appendChild(card);
132→  });
133→
134→  document.getElementById("category-next").addEventListener("click", function () {
135→    clearError("category-error");
136→    hide(stepCategory);
137→    show(stepTrip);
138→    hide(stepDetails);
139→    loadTrips();
140→    window.scrollTo(0, 0);
141→  });
142→
143→  // ------------------------------------------------------------- step two
144→
145→  function loadTrips() {
146→    var boxes = tripOptions;
147→    while (boxes.firstChild) {
148→      boxes.removeChild(boxes.firstChild);
149→    }
150→    state.tripId = null;
151→    document.getElementById("trip-next").disabled = true;
152→    boxes.appendChild(element("p", "loading", "Loading trips…"));
153→    request("GET", "/api/trips?category=" + encodeURIComponent(state.category))
154→      .then(function (payload) {
155→        while (boxes.firstChild) {
156→          boxes.removeChild(boxes.firstChild);
157→        }
158→        state.trips = Array.isArray(payload.trips) ? payload.trips : [];
159→        if (state.trips.length === 0) {
160→          boxes.appendChild(element("p", "hint", "No trips are available in the sample dataset."));
161→          return;
162→        }
163→        state.trips.forEach(function (trip) {
164→          var meta = [trip.date, trip.kind_label].filter(Boolean).join(" · ");
165→          var lines = [
166→            element("strong", null, trip.label),
167→            element("span", "trip-meta", meta)
168→          ];
169→          var charge = "";
170→          if (trip.fare_sgd !== null && trip.fare_sgd !== undefined) {
171→            charge = " · SGD " + Number(trip.fare_sgd).toFixed(2)
172→              + (trip.charge_label ? " " + trip.charge_label : "");
173→          }
174→          var detail = element("span", "trip-meta", "");
175→          detail.textContent = "Trip " + trip.trip_id + charge;
176→          var card = element("button", "option-card trip-card");
177→          card.type = "button";
178→          lines.forEach(function (line) { card.appendChild(line); });
179→          card.appendChild(detail);
180→          card.addEventListener("click", function () {
181→            state.tripId = trip.trip_id;
182→            Array.prototype.forEach.call(boxes.children, function (child) {
183→              child.classList.remove("selected");
184→            });
185→            card.classList.add("selected");
186→            document.getElementById("trip-next").disabled = false;
187→          });
188→          boxes.appendChild(card);
189→        });
190→      })
191→      .catch(function (error) {
192→        while (boxes.firstChild) {
193→          boxes.removeChild(boxes.firstChild);
194→        }
195→        showError("trip-error", error.message);
196→      });
197→  }
198→
199→  document.getElementById("trip-back").addEventListener("click", function () {
200→    show(stepCategory);
201→    hide(stepTrip);
202→  });
203→
204→  document.getElementById("trip-next").addEventListener("click", function () {
205→    clearError("trip-error");
206→    hide(stepTrip);
207→    buildQuestions();
208→    show(stepDetails);
209→    window.scrollTo(0, 0);
