212→  // --------------------------------------------------------- step three
213→
214→  function buildQuestions() {
215→    while (questionList.firstChild) {
216→      questionList.removeChild(questionList.firstChild);
217→    }
218→    var questions = QUESTIONNAIRES[state.category] || [];
219→    questions.forEach(function (question) {
220→      var field = element("div", "field");
221→      var label = element("label", null, question.label);
222→      label.htmlFor = "answer-" + question.key;
223→      var input = element("textarea", "answer-input");
224→      input.id = "answer-" + question.key;
225→      input.rows = 2;
226→      input.dataset.questionKey = question.key;
227→      field.appendChild(label);
228→      field.appendChild(input);
229→      questionList.appendChild(field);
230→    });
231→  }
232→
233→  document.getElementById("details-back").addEventListener("click", function () {
234→    hide(stepDetails);
235→    show(stepTrip);
236→    loadTrips();
237→  });
