239→  document.getElementById("details-form").addEventListener("submit", function (event) {
240→    event.preventDefault();
241→    clearError("details-error");
242→    var description = document.getElementById("description").value;
243→    if (!description.trim()) {
244→      showError("details-error", "Please tell us what happened before sending.");
245→      return;
246→    }
247→    var amountText = document.getElementById("claim-amount").value.trim();
248→    var amount = null;
249→    if (amountText !== "") {
250→      amount = Number(amountText);
251→      if (!isFinite(amount) || amount < 0 || amount > 500) {
252→        showError("details-error", "The amount must be between 0 and 500 SGD.");
253→        return;
254→      }
255→    }
256→    var answers = {};
257→    Array.prototype.forEach.call(questionList.querySelectorAll("textarea"), function (input) {
258→      answers[input.dataset.questionKey] = input.value;
259→    });
260→
261→    var submit = document.getElementById("details-submit");
262→    submit.disabled = true;
263→    request("POST", "/api/disputes", {
264→      category: state.category,
265→      filed_by: "rider",
266→      trip_id: state.tripId,
267→      description: description,
268→      claim_amount_sgd: amount,
269→      answers: answers
270→    })
271→      .then(function (view) {
272→        renderOutcome(view);
273→      })
274→      .catch(function (error) {
275→        submit.disabled = false;
276→        showError("details-error", error.message);
277→      });
278→  });
279→
280→  // ------------------------------------------------------------- outcome
281→
282→  function renderOutcome(view) {
283→    hide(document.getElementById("form-steps"));
284→    show(outcomePanel);
285→    state.runId = view.run_id;
286→    outcomeTitle.textContent = STATUS_HEADINGS[view.status] || "Your dispute has been received";
287→    outcomeReference.textContent = view.dispute_id;
288→    outcomeMessage.textContent = view.message;
289→    hide(outcomeStatus);
290→    buildAnswerBoxes(view);
291→    window.scrollTo(0, 0);
292→  }
293→
294→  function buildAnswerBoxes(view) {
295→    while (questionBoxes.firstChild) {
296→      questionBoxes.removeChild(questionBoxes.firstChild);
297→    }
298→    var questions = Array.isArray(view.questions) ? view.questions : [];
299→    if (view.status !== "needs_info" || questions.length === 0) {
300→      hide(outcomeQuestions);
301→      return;
302→    }
303→    show(outcomeQuestions);
304→    questions.forEach(function (question, index) {
305→      var field = element("div", "field");
306→      var label = element("label", null, question);
307→      label.htmlFor = "reply-" + index;
308→      var input = element("textarea", "answer-input");
309→      input.id = "reply-" + index;
310→      input.rows = 2;
311→      field.appendChild(label);
312→      field.appendChild(input);
313→      questionBoxes.appendChild(field);
314→    });
315→  }
316→
317→  document.getElementById("answers-submit").addEventListener("click", function () {
318→    clearError("answers-error");
319→    var replies = [];
320→    var complete = true;
321→    Array.prototype.forEach.call(questionBoxes.querySelectorAll("textarea"), function (input) {
322→      var label = questionBoxes.querySelector('label[for="' + input.id + '"]');
323→      replies.push({ question: label ? label.textContent : "", answer: input.value });
324→      if (!input.value.trim()) {
325→        complete = false;
326→      }
327→    });
328→    if (!complete) {
329→      showError("answers-error", "Please answer each question before sending.");
330→      return;
331→    }
332→    var submit = document.getElementById("answers-submit");
333→    submit.disabled = true;
334→    outcomeStatus.textContent = "Sending your answers…";
335→    show(outcomeStatus);
336→    request("POST", "/api/disputes/" + encodeURIComponent(state.runId) + "/answers", {
337→      answers: replies
338→    })
339→      .then(function (view) {
340→        renderOutcome(view);
341→      })
342→      .catch(function (error) {
343→        submit.disabled = false;
344→        hide(outcomeStatus);
345→        showError("answers-error", error.message);
346→      });
347→  });
348→}());
